419	// 待判定样品没有判定记录、待判定后作废的样品没有历史依据，都仍是正常情况；
420	// 已确认后作废但历史依据完整的样品也继续兼容（列表可查、最近结果跳过、
421	// 再确认拒绝）。
422	func TestOpenPendingAndVoidedSamples(t *testing.T) {
423		dir := t.TempDir()
424		writeDiskFile(t, dir, diskState{
425			Points: map[string]SamplingPoint{
426				"P1": {ID: "P1", Name: "一号取水口"},
427				"P2": {ID: "P2", Name: "二号取水口"},
428			},
429			Samples: map[string]*Sample{
430				// 待判定：无判定记录。
431				"SP": {
432					ID: "SP", PointID: "P1", SampledAt: at(2, 0),
433					Measurements: []Measurement{{Item: openPH, Value: 9}},
434					Status:       StatusPending,
435				},
436				// 待判定后作废：无历史依据。
437				"SV": {
438					ID: "SV", PointID: "P1", SampledAt: at(3, 0),
439					Measurements: []Measurement{{Item: openPH, Value: 9}},
440					Status:       StatusVoided, VoidReason: "录入信息有误",
441				},
442				// 已确认后作废：历史依据完整。
443				"SCV": {
444					ID: "SCV", PointID: "P2", SampledAt: at(4, 0),
445					Measurements: []Measurement{{Item: openPH, Value: 9}},
446					Status:       StatusVoided, VoidReason: "复测确认样品污染", Exceeded: true,
447					Results: []ItemResult{
448						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: true},
449					},
450				},
451			},
452		})
453		s, err := Open(dir)
454		if err != nil {
455			t.Fatalf("待判定与无历史依据的作废样品都应正常读入: %v", err)
456		}
457		defer s.Close()
458	
459		p1, err := s.ListByPoint("P1")
460		if err != nil || len(p1) != 2 {
461			t.Fatalf("P1 列表: %+v err=%v", p1, err)
462		}
463		byID := map[string]Sample{}
464		for _, smp := range p1 {
465			byID[smp.ID] = smp
466		}
467		sp := byID["SP"]
468		if sp.Status != StatusPending || sp.Results != nil || sp.Exceeded {
469			t.Fatalf("待判定样品读入后不应带结论: %+v", sp)
470		}
471		sv := byID["SV"]
472		if sv.Status != StatusVoided || sv.VoidReason != "录入信息有误" ||
473			len(sv.Results) != 0 || sv.Exceeded {
474			t.Fatalf("待判定后作废样品不应凭空获得结论: %+v", sv)
475		}
476		// P1 没有已确认且未作废的样品：明确无结果。
477		if latest, ok, err := s.LatestResult("P1"); err != nil || ok {
478			t.Fatalf("P1 应无最近有效结果: %+v ok=%v err=%v", latest, ok, err)
479		}
480	
481		// 已确认后作废的完整历史记录继续兼容。
482		p2, err := s.ListByPoint("P2")
483		if err != nil || len(p2) != 1 {
484			t.Fatalf("P2 列表: %+v err=%v", p2, err)
485		}
486		scv := p2[0]
487		if scv.Status != StatusVoided || !scv.Exceeded || len(scv.Results) != 1 {
488			t.Fatalf("已确认后作废的历史依据应保留: %+v", scv)
489		}
490		if r := scv.Results[0]; r.Item != openPH || r.Value != 9 || r.Limit != 8 ||
491			!r.LimitEffective.Equal(openEff()) || !r.Exceeded {
492			t.Fatalf("历史判定依据被改动: %+v", r)
493		}
494		if latest, ok, err := s.LatestResult("P2"); err != nil || ok {
495			t.Fatalf("作废样品不应作为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
496		}
497		if _, err := s.Confirm("SCV"); !errors.Is(err, ErrVoided) {
498			t.Fatalf("已作废样品再确认应被拒绝，got %v", err)
499		}
500	}
