904	// assertOpenRejectsWholeFlag 断言整份超标标记与逐项结论矛盾时整次 Open 失败：
905	// 返回 nil 存放、ErrCorruptRecord、信息点名样品编号并说明与逐项结论不一致，
906	// 原文件字节不变；不要求信息里出现某个项目名。
907	func assertOpenRejectsWholeFlag(t *testing.T, dir, sampleID string) {
908		t.Helper()
909		before, err := os.ReadFile(filepath.Join(dir, "water-data.json"))
910		if err != nil {
911			t.Fatalf("read file before open: %v", err)
912		}
913		got, err := Open(dir)
914		if err == nil {
915			if got != nil {
916				got.Close()
917			}
918			t.Fatalf("整份标记矛盾必须让整次 Open 失败，sample=%s", sampleID)
919		}
920		if got != nil {
921			t.Fatalf("打开失败时不得返回可用的数据存放对象，got %#v", got)
922		}
923		if !errors.Is(err, ErrCorruptRecord) {
924			t.Fatalf("应返回 ErrCorruptRecord，got %v", err)
925		}
926		msg := err.Error()
927		if !strings.Contains(msg, sampleID) {
928			t.Fatalf("错误信息应指出样品编号 %q，实际 %q", sampleID, msg)
929		}
930		if !strings.Contains(msg, "逐项") {
931			t.Fatalf("错误信息应说明整份标记与逐项结论不一致，实际 %q", msg)
932		}
933		after, rerr := os.ReadFile(filepath.Join(dir, "water-data.json"))
934		if rerr != nil {
935			t.Fatalf("read file after open: %v", rerr)
936		}
937		if string(after) != string(before) {
938			t.Fatalf("打开失败不得覆盖或改写原数据文件")
939		}
940	}
