1145				"S-GOOD": {
1146					ID: "S-GOOD", PointID: "P1", SampledAt: at(5, 0),
1147					Measurements: []Measurement{{Item: openPH, Value: 7}},
1148					Status:       StatusConfirmed, Exceeded: false,
1149					Results: []ItemResult{
1150						{Item: openPH, Value: 7, Limit: 8, LimitEffective: openEff(), Exceeded: false},
1151					},
1152				},
1153				// 测量值 9、上限 8 却标成达标的损坏样品。
1154				"S-BAD": {
1155					ID: "S-BAD", PointID: "P1", SampledAt: at(10, 0),
1156					Measurements: []Measurement{{Item: openPH, Value: 9}},
1157					Status:       StatusConfirmed, Exceeded: false,
1158					Results: []ItemResult{
1159						{Item: openPH, Value: 9, Limit: 8, LimitEffective: openEff(), Exceeded: false},
1160					},
1161				},
1162			},
1163		})
1164		assertOpenRejects(t, dir, "S-BAD", openPH, false)
1165	}
1166	
1167	// 核对只针对这份样品已保存的判定依据：保存的上限是 100、测量值 9 且标记达标，
1168	// 即使文件里另有当前会选到的更严限值（8，超标），只要旧结论与旧依据一致就
1169	// 照常打开，所用上限、生效时间和结论原样保留，不重新选择限值、不重做判定。
1170	func TestOpenFlagCheckedAgainstSavedBasisOnly(t *testing.T) {
1171		dir := t.TempDir()
1172		writeDiskFile(t, dir, diskState{
1173			Points: openPoints(),
1174			Limits: map[string][]Limit{
1175				diskLimitKey("P1", openPH): {
1176					{PointID: "P1", Item: openPH, Value: 8, Effective: at(1, 0)},
1177				},
1178			},
1179			Samples: map[string]*Sample{
1180				"S1": {
1181					ID: "S1", PointID: "P1", SampledAt: at(10, 0),
1182					Measurements: []Measurement{{Item: openPH, Value: 9}},
1183					Status:       StatusConfirmed, Exceeded: false,
1184					Results: []ItemResult{
1185						// 保存的旧依据是 9 <= 100 达标；按当前限值 8 重算会变成超标。
1186						{Item: openPH, Value: 9, Limit: 100, LimitEffective: at(2, 0), Exceeded: false},
1187					},
1188				},
1189			},
1190		})
1191		s, err := Open(dir)
1192		if err != nil {
1193			t.Fatalf("旧结论与旧依据一致时应正常读入，不能按当前限值重判: %v", err)
1194		}
1195		defer s.Close()
1196		latest, ok, err := s.LatestResult("P1")
1197		if err != nil || !ok || latest.ID != "S1" {
1198			t.Fatalf("正常记录应可作为最近有效结果: %+v ok=%v err=%v", latest, ok, err)
1199		}
1200		r := latest.Results[0]
1201		if r.Value != 9 || r.Limit != 100 || !r.LimitEffective.Equal(at(2, 0)) || r.Exceeded || latest.Exceeded {
1202			t.Fatalf("旧上限、生效时间与达标结论必须原样保留: %+v exceeded=%v", r, latest.Exceeded)
1203		}
1204	}
1205	
1206	// 保存依据是 9 <= 100 达标，却把单项标记写成超标：即使该标记恰好与当前更严
1207	// 限值（8）会得出的结论相同，它仍与这份样品保存的依据矛盾，必须拒绝。
1208	func TestOpenFlagContradictsSavedBasisEvenIfCurrentLimitAgrees(t *testing.T) {
1209		dir := t.TempDir()
1210		writeDiskFile(t, dir, diskState{
1211			Points: openPoints(),
1212			Limits: map[string][]Limit{
1213				diskLimitKey("P1", openPH): {
