1	package water
2	
3	import (
4		"errors"
5		"math"
6		"os"
7		"path/filepath"
8		"testing"
9		"time"
10	)
11	
12	func open(t *testing.T) (*Store, string) {
13		t.Helper()
14		dir := t.TempDir()
15		s, err := Open(dir)
16		if err != nil {
17			t.Fatalf("Open: %v", err)
18		}
19		t.Cleanup(func() { s.Close() })
20		return s, dir
21	}
22	
23	func mustPoint(t *testing.T, s *Store, id, name string) {
24		t.Helper()
25		if _, err := s.RegisterPoint(id, name); err != nil {
26			t.Fatalf("RegisterPoint(%q): %v", id, err)
27		}
28	}
29	
30	func mustLimit(t *testing.T, s *Store, point, item string, v float64, eff time.Time) {
31		t.Helper()
32		if _, err := s.SetLimit(point, item, v, eff); err != nil {
33			t.Fatalf("SetLimit(%s/%s): %v", point, item, err)
34		}
35	}
36	
37	func mustSample(t *testing.T, s *Store, id, point string, at time.Time, ms ...Measurement) Sample {
38		t.Helper()
39		smp, err := s.SubmitSample(id, point, at, ms...)
40		if err != nil {
41			t.Fatalf("SubmitSample(%q): %v", id, err)
42		}
43		return smp
44	}
45	
46	func at(day, hour int) time.Time {
47		return time.Date(2026, 9, day, hour, 0, 0, 0, time.UTC)
48	}
49	
50	func TestRegisterPoint(t *testing.T) {
51		s, _ := open(t)
52		p, err := s.RegisterPoint("  P1 ", "  取水口  ")
53		if err != nil {
54			t.Fatalf("RegisterPoint: %v", err)
55		}
56		if p.ID != "P1" || p.Name != "取水口" {
57			t.Fatalf("expected trimmed text, got %+v", p)
58		}
59		if _, err := s.RegisterPoint("P1", "另一个名字"); !errors.Is(err, ErrDuplicatePoint) {
60			t.Fatalf("duplicate id should be rejected, got %v", err)
61		}
62		for _, id := range []string{"", "   "} {
63			if _, err := s.RegisterPoint(id, "x"); !errors.Is(err, ErrEmptyField) {
64				t.Fatalf("empty id should be rejected, got %v", err)
65			}
66		}
67		if _, err := s.RegisterPoint("P2", "  "); !errors.Is(err, ErrEmptyField) {
68			t.Fatalf("empty name should be rejected, got %v", err)
69		}
70	}
71	
72	func TestSetLimit(t *testing.T) {
73		s, _ := open(t)
74		mustPoint(t, s, "P1", "取水口")
75	
76		if _, err := s.SetLimit("P9", "pH", 7, at(1, 0)); !errors.Is(err, ErrUnknownPoint) {
77			t.Fatalf("unknown point, got %v", err)
78		}
79		if _, err := s.SetLimit("P1", " ", 7, at(1, 0)); !errors.Is(err, ErrEmptyField) {
80			t.Fatalf("blank item, got %v", err)
81		}
82		if _, err := s.SetLimit("P1", "pH", math.NaN(), at(1, 0)); !errors.Is(err, ErrInvalidValue) {
83			t.Fatalf("NaN, got %v", err)
84		}
85		if _, err := s.SetLimit("P1", "pH", math.Inf(1), at(1, 0)); !errors.Is(err, ErrInvalidValue) {
86			t.Fatalf("+Inf, got %v", err)
87		}
88		if _, err := s.SetLimit("P1", "pH", 7, time.Time{}); !errors.Is(err, ErrInvalidTime) {
89			t.Fatalf("zero time, got %v", err)
90		}
91	
92		// 乱序补录
93		mustLimit(t, s, "P1", "pH", 8.0, at(10, 0))
94		mustLimit(t, s, "P1", "pH", 6.5, at(1, 0))
95		mustLimit(t, s, "P1", "pH", 7.0, at(5, 0))
96	
97		// 生效时间相同（含不同时区表示的同一时刻）拒绝，且不覆盖原值
98		same := time.Date(2026, 9, 5, 8, 0, 0, 0, time.FixedZone("CST", 8*3600)) // == at(5,0) UTC
99		if _, err := s.SetLimit("P1", "pH", 9.9, same); !errors.Is(err, ErrDuplicateLimitTime) {
100			t.Fatalf("same instant in another zone, got %v", err)
101		}
102		if _, err := s.SetLimit("P1", "pH", 9.9, at(5, 0)); !errors.Is(err, ErrDuplicateLimitTime) {
103			t.Fatalf("same effective time, got %v", err)
104		}
105	
106		// 原值未被覆盖：确认 at(6,0) 的样品应使用 7.0
107		mustSample(t, s, "S1", "P1", at(6, 0), Measurement{Item: "pH", Value: 7.5})
108		smp, err := s.Confirm("S1")
109		if err != nil {
110			t.Fatalf("Confirm: %v", err)
111		}
112		if smp.Results[0].Limit != 7.0 {
113			t.Fatalf("limit overwritten by rejected entry: %+v", smp.Results[0])
114		}
115	}
116	
117	// 新增限值保存失败时，当前打开的数据存放必须完整保持调用前的状态：
118	// 被拒绝的限值不能继续参与判定，原有版本及其适用时间不能丢失或错乱；
119	// 条件恢复后相同补录可重试成功，且失败期间的其它成功操作不能把
120	// 被拒绝的限值或版本丢失顺带落盘。
121	func TestSetLimitPersistFailure(t *testing.T) {
122		s, dir := open(t)
123		mustPoint(t, s, "P1", "取水口")
124		mustLimit(t, s, "P1", "pH", 10.0, at(1, 0))
125		mustLimit(t, s, "P1", "pH", 20.0, at(10, 0))
126		mustLimit(t, s, "P1", "pH", 30.0, at(20, 0))
127	
128		// 让落盘失败：把临时文件路径占成目录，WriteFile 必然失败
129		tmp := filepath.Join(dir, "water-data.json.tmp")
130		if err := os.Mkdir(tmp, 0o755); err != nil {
131			t.Fatalf("block persist: %v", err)
132		}
133		// 乱序补录到已有版本之间，保存失败
134		if _, err := s.SetLimit("P1", "pH", 5.0, at(5, 0)); err == nil {
135			t.Fatal("SetLimit should fail when persist fails")
136		}
137		// 失败发生在更晚生效的版本上同样不能丢原有版本
138		if _, err := s.SetLimit("P1", "pH", 35.0, at(25, 0)); err == nil {
139			t.Fatal("SetLimit should fail when persist fails")
140		}
141		// 恢复正常保存条件
142		if err := os.Remove(tmp); err != nil {
143			t.Fatalf("restore persist: %v", err)
144		}
145	
146		// 9/6 采样、值 8：必须使用 9/1 的上限 10 判为达标，不能用被拒绝的 5
147		mustSample(t, s, "S1", "P1", at(6, 0), Measurement{Item: "pH", Value: 8})
148		smp1, err := s.Confirm("S1")
149		if err != nil {
150			t.Fatalf("Confirm S1: %v", err)
151		}
152		if smp1.Results[0].Limit != 10.0 || smp1.Exceeded {
153			t.Fatalf("rejected limit leaked into judgment: %+v", smp1.Results[0])
154		}
155		// 9/21 采样、值 25：必须使用 9/20 的上限 30 判为达标，不能因版本丢失退回 20
156		mustSample(t, s, "S2", "P1", at(21, 0), Measurement{Item: "pH", Value: 25})
157		smp2, err := s.Confirm("S2")
158		if err != nil {
159			t.Fatalf("Confirm S2: %v", err)
160		}
161		if smp2.Results[0].Limit != 30.0 || smp2.Exceeded {
162			t.Fatalf("original version lost after failed save: %+v", smp2.Results[0])
163		}
164	
165		// 相同补录可以重试成功，不能把上次失败当成已登记
166		mustLimit(t, s, "P1", "pH", 5.0, at(5, 0))
167	
168		// 成功补录后，尚未确认且采样于 9/6 的样品使用上限 5
169		mustSample(t, s, "S3", "P1", at(6, 0), Measurement{Item: "pH", Value: 8})
170		smp3, err := s.Confirm("S3")
171		if err != nil {
172			t.Fatalf("Confirm S3: %v", err)
173		}
174		if smp3.Results[0].Limit != 5.0 || !smp3.Exceeded {
175			t.Fatalf("backfilled limit should apply to pending sample: %+v", smp3.Results[0])
176		}
177		// 已确认样品保留原判定及所用限值，重复确认不重新计算
178		again1, err := s.Confirm("S1")
179		if err != nil || again1.Results[0].Limit != 10.0 || again1.Exceeded {
180			t.Fatalf("confirmed result must not change, got %+v err=%v", again1.Results[0], err)
181		}
182		again2, err := s.Confirm("S2")
183		if err != nil || again2.Results[0].Limit != 30.0 || again2.Exceeded {
184			t.Fatalf("confirmed result must not change, got %+v err=%v", again2.Results[0], err)
185		}
186		if err := s.Close(); err != nil {
187			t.Fatalf("Close: %v", err)
188		}
189	
190		// 重新打开：应看到最后成功保存的限值状态——四版俱在，
191		// 被拒绝且未重试的 35@9/25 不能被失败期间的成功操作顺带保存进去
192		s2, err := Open(dir)
193		if err != nil {
194			t.Fatalf("reopen: %v", err)
195		}
196		defer s2.Close()
197		mustSample(t, s2, "S4", "P1", at(6, 0), Measurement{Item: "pH", Value: 8})
198		smp4, err := s2.Confirm("S4")
199		if err != nil || smp4.Results[0].Limit != 5.0 || !smp4.Exceeded {
200			t.Fatalf("reopened: 9/6 should use backfilled 5, got %+v err=%v", smp4.Results[0], err)
201		}
202		mustSample(t, s2, "S5", "P1", at(21, 0), Measurement{Item: "pH", Value: 25})
203		smp5, err := s2.Confirm("S5")
204		if err != nil || smp5.Results[0].Limit != 30.0 || smp5.Exceeded {
205			t.Fatalf("reopened: 9/21 should use 30, got %+v err=%v", smp5.Results[0], err)
206		}
207		mustSample(t, s2, "S6", "P1", at(24, 0), Measurement{Item: "pH", Value: 31})
208		smp6, err := s2.Confirm("S6")
209		if err != nil || smp6.Results[0].Limit != 30.0 || !smp6.Exceeded {
210			t.Fatalf("reopened: rejected 35@9/25 must not exist, got %+v err=%v", smp6.Results[0], err)
211		}
212	}
213	
214	func TestSubmitSample(t *testing.T) {
215		s, _ := open(t)
216		mustPoint(t, s, "P1", "取水口")
217	
218		if _, err := s.SubmitSample("S1", "P9", at(1, 0), Measurement{Item: "pH", Value: 7}); !errors.Is(err, ErrUnknownPoint) {
219			t.Fatalf("unknown point, got %v", err)
220		}
221		if _, err := s.SubmitSample("S1", "P1", time.Time{}, Measurement{Item: "pH", Value: 7}); !errors.Is(err, ErrInvalidTime) {
222			t.Fatalf("zero time, got %v", err)
223		}
224		if _, err := s.SubmitSample("S1", "P1", at(1, 0)); !errors.Is(err, ErrNoMeasurements) {
225			t.Fatalf("no measurements, got %v", err)
226		}
227		if _, err := s.SubmitSample("S1", "P1", at(1, 0), Measurement{Item: "pH", Value: math.Inf(-1)}); !errors.Is(err, ErrInvalidValue) {
228			t.Fatalf("-Inf, got %v", err)
229		}
230		if _, err := s.SubmitSample("S1", "P1", at(1, 0),
231			Measurement{Item: " pH ", Value: 7}, Measurement{Item: "pH", Value: 8}); !errors.Is(err, ErrDuplicateItem) {
232			t.Fatalf("duplicate item, got %v", err)
233		}
234	
235		smp := mustSample(t, s, "S1", "P1", at(1, 0),
236			Measurement{Item: "pH", Value: 7}, Measurement{Item: "COD", Value: 20})
237		if smp.Status != StatusPending {
238			t.Fatalf("new sample should be pending, got %s", smp.Status)
239		}
240	
241		// 同编号同内容（项目顺序不同、时间用另一时区表示）返回原样品
242		again, err := s.SubmitSample("S1", "P1",
243			time.Date(2026, 9, 1, 8, 0, 0, 0, time.FixedZone("CST", 8*3600)),
244			Measurement{Item: "COD", Value: 20}, Measurement{Item: "pH", Value: 7})
245		if err != nil {
246			t.Fatalf("idempotent resubmit: %v", err)
247		}
248		if again.ID != "S1" || again.Status != StatusPending {
249			t.Fatalf("expected original sample, got %+v", again)
250		}
251	
252		// 任一内容不同则拒绝
253		cases := []struct {
254			point string
255			at    time.Time
256			ms    []Measurement
257		}{
258			{"P1", at(2, 0), []Measurement{{Item: "pH", Value: 7}, {Item: "COD", Value: 20}}},
259			{"P1", at(1, 0), []Measurement{{Item: "pH", Value: 7}}},
260			{"P1", at(1, 0), []Measurement{{Item: "pH", Value: 7}, {Item: "COD", Value: 21}}},
261			{"P1", at(1, 0), []Measurement{{Item: "pH", Value: 7}, {Item: "COD", Value: 20}, {Item: "SS", Value: 5}}},
262		}
263		for i, c := range cases {
264			if _, err := s.SubmitSample("S1", c.point, c.at, c.ms...); !errors.Is(err, ErrSampleConflict) {
265				t.Fatalf("case %d: conflicting resubmit should be rejected, got %v", i, err)
266			}
267		}
268	}
269	
270	// 新样品的提交内容本身合法、但本地数据写入失败时，本次录入必须整体失败：
271	// 返回保存错误和空样品，不能返回带编号的待判定记录。按采样点查看仍只有
272	// 此前成功保存的样品；对失败提交的编号请求确认，必须明确报样品不存在，
273	// 不能转而开始判定，也不能报缺少适用上限。较早样品的原始测量、确认状态、
274	// 逐项所用上限与生效时间以及整份结论保持原样，最近有效结果仍指向它。
275	// 保存条件未恢复期间，同编号同内容再次提交仍因保存失败被拒绝，不能走已有
276	// 样品的幂等重报返回成功；恢复后用同编号、把其中一个测量值改为另一个有限数
277	// 再次录入，应作为首次成功录入接受，不能因前一次失败内容不同而报冲突。
278	// 失败尝试的测量值不能被随后一次成功录入顺带保存，重新打开数据存放后
279	// 只看得到成功提交的内容。同一份提交内项目重复属于内容校验，即使本地同样
280	// 无法写入也必须返回现有的项目重复错误，不能与合法提交遇写入失败混为一种失败。
281	func TestSubmitSamplePersistFailure(t *testing.T) {
282		s, dir := open(t)
283		mustPoint(t, s, "P1", "取水口")
284		mustLimit(t, s, "P1", "pH", 8.0, at(1, 0))
285		mustLimit(t, s, "P1", "COD", 30.0, at(1, 0))
286	
287		find := func(list []Sample, id string) Sample {
288			t.Helper()
289			for _, smp := range list {
290				if smp.ID == id {
291					return smp
292				}
293			}
294			t.Fatalf("sample %q missing from list %+v", id, list)
295			return Sample{}
296		}
297		valuesOf := func(smp Sample) map[string]float64 {
298			m := make(map[string]float64, len(smp.Measurements))
299			for _, msm := range smp.Measurements {
300				m[msm.Item] = msm.Value
301			}
302			return m
303		}
304		// 较早样品 S1 应始终保持的完整记录：pH 9 > 8@09-01 超标，
305		// COD 30 == 30@09-01 达标，整份超标，已确认。
306		checkEarlier := func(smp Sample, label string) {
307			t.Helper()
308			if smp.ID != "S1" || smp.PointID != "P1" || smp.Status != StatusConfirmed || smp.VoidReason != "" {
309				t.Fatalf("%s: 较早样品的编号、采样点、状态或作废原因被改动: %+v", label, smp)
310			}
311			if !smp.SampledAt.Equal(at(5, 0)) || !smp.Exceeded {
312				t.Fatalf("%s: 采样时间或整份结论被改动: %+v", label, smp)
313			}
314			if len(smp.Measurements) != 2 || len(smp.Results) != 2 {
315				t.Fatalf("%s: 测量或逐项结果数量被改动: %+v", label, smp)
316			}
317			if ms := valuesOf(smp); ms["pH"] != 9 || ms["COD"] != 30 {
318				t.Fatalf("%s: 原始测量被改动: %+v", label, smp.Measurements)
319			}
320			rs := map[string]ItemResult{}
321			for _, r := range smp.Results {
322				rs[r.Item] = r
323			}
324			if ph := rs["pH"]; ph.Value != 9 || ph.Limit != 8.0 || !ph.LimitEffective.Equal(at(1, 0)) || !ph.Exceeded {
325				t.Fatalf("%s: pH 逐项所用上限与生效时间被改动: %+v", label, ph)
326			}
327			if cod := rs["COD"]; cod.Value != 30 || cod.Limit != 30.0 || !cod.LimitEffective.Equal(at(1, 0)) || cod.Exceeded {
328				t.Fatalf("%s: COD 逐项所用上限与生效时间被改动: %+v", label, cod)
329			}
330		}
331	
332		// 较早、采样于 9/5 的双项目样品正常录入并确认，作为此前唯一成功保存的样品。
333		mustSample(t, s, "S1", "P1", at(5, 0),
334			Measurement{Item: "pH", Value: 9}, Measurement{Item: "COD", Value: 30})
335		conf1, err := s.Confirm("S1")
336		if err != nil {
337			t.Fatalf("Confirm S1 setup: %v", err)
338		}
339		checkEarlier(conf1, "setup 确认返回值")
340	
341		// 只让新样品的保存失败：采样点、限值和较早样品此前均已成功落盘。
342		// 占用临时文件路径为目录后，原子写的 WriteFile 必然失败，不依赖目录权限。
343		tmp := filepath.Join(dir, "water-data.json.tmp")
344		if err := os.Mkdir(tmp, 0o755); err != nil {
345			t.Fatalf("block persist: %v", err)
346		}
347	
348		// 合法的新样品：编号全新、采样时间更晚、两个不同项目，测量值都是有限数。
349		failed := []Measurement{{Item: "pH", Value: 7}, {Item: "COD", Value: 25}}
350		got, err := s.SubmitSample("S2", "P1", at(10, 0), failed...)
351		if err == nil {
352			t.Fatal("SubmitSample should fail when the new sample cannot be saved")
353		}
354		// 必须是保存错误，不能冒充任何一种提交内容校验失败。
355		for _, target := range []error{
356			ErrEmptyField, ErrInvalidTime, ErrNoMeasurements, ErrInvalidValue,
357			ErrDuplicateItem, ErrUnknownPoint, ErrSampleConflict,
358		} {
359			if errors.Is(err, target) {
360				t.Fatalf("save failure must not be reported as %v: %v", target, err)
361			}
362		}
363		// 返回空样品：连编号和待判定状态都没有，调用方不能当录入成功使用。
364		if got.ID != "" || got.Status != "" {
365			t.Fatalf("failed save must return an empty sample, got %+v", got)
366		}
367		// 内存状态同步回滚，随后的成功保存不能把失败尝试顺带写入。
368		if _, ok := s.samples["S2"]; ok {
369			t.Fatal("failed sample must be rolled back from the in-memory store")
370		}
371	
372		// 按采样点查看仍只有此前成功保存的 S1，原测量、判定依据与整份结论原样。
373		list, err := s.ListByPoint("P1")
374		if err != nil || len(list) != 1 || list[0].ID != "S1" {
375			t.Fatalf("ListByPoint after failed save: %+v err=%v", list, err)
376		}
377		checkEarlier(list[0], "保存失败后按点查看")
378		// 重复确认较早样品，仍返回原来保存的结论。
379		again1, err := s.Confirm("S1")
380		if err != nil {
381			t.Fatalf("Confirm S1 after failed save: %v", err)
382		}
383		checkEarlier(again1, "保存失败后重复确认较早样品")
384	
385		// 对失败提交的编号请求确认：明确报样品不存在。两个项目的适用上限都在，
386		// 因此这既不能转而开始判定，也不能是缺少适用上限。
387		probe, err := s.Confirm("S2")
388		if !errors.Is(err, ErrUnknownSample) || probe.ID != "" {
389			t.Fatalf("failed submit must leave no sample to confirm, got sample=%+v err=%v", probe, err)
390		}
391	
392		// 最近有效结果仍指向较早样品，逐项依据与整份结论保持原样。
393		latest, ok, err := s.LatestResult("P1")
394		if err != nil || !ok || latest.ID != "S1" {
395			t.Fatalf("latest valid result should stay S1, got %+v ok=%v err=%v", latest, ok, err)
396		}
397		checkEarlier(latest, "保存失败后最近有效结果")
398	
399		// 保存条件尚未恢复：同编号、同内容再次提交，仍应因保存失败被拒绝，
400		// 不能因为编号“似乎提交过”而走已有样品的幂等重报返回成功。
401		got2, err := s.SubmitSample("S2", "P1", at(10, 0), failed...)
402		if err == nil {
403			t.Fatal("resubmit while saving still fails should be rejected")
404		}
405		if errors.Is(err, ErrSampleConflict) || errors.Is(err, ErrDuplicateItem) {
406			t.Fatalf("repeated valid submit must fail with the save error, got %v", err)
407		}
408		if got2.ID != "" || got2.Status != "" {
409			t.Fatalf("repeated failed save must return an empty sample, got %+v", got2)
410		}
411	
412		// 同一份提交内项目重复属于内容校验：即使本地同样无法写入，也必须在保存
413		// 之前返回现有的项目重复错误，不能与合法提交遇写入失败混为一种失败。
414		if _, err := s.SubmitSample("S2", "P1", at(10, 0),
415			Measurement{Item: "pH", Value: 7}, Measurement{Item: "pH", Value: 8}); !errors.Is(err, ErrDuplicateItem) {
416			t.Fatalf("duplicate item must be rejected before save (same id), got %v", err)
417		}
418		if _, err := s.SubmitSample("S9", "P1", at(10, 0),
419			Measurement{Item: "COD", Value: 1}, Measurement{Item: "COD", Value: 2}); !errors.Is(err, ErrDuplicateItem) {
420			t.Fatalf("duplicate item must be rejected before save (new id), got %v", err)
421		}
422		// 被内容校验拒绝的提交同样不能留下编号，成功录入后也不能把它顺带落盘。
423		if _, ok := s.samples["S9"]; ok {
424			t.Fatal("duplicate-item submission must not leave a sample")
425		}
426	
427		// 恢复正常保存条件。
428		if err := os.Remove(tmp); err != nil {
429			t.Fatalf("restore persist: %v", err)
430		}
431	
432		// 用同一编号继续录入，把 pH 改成另一个有限数 6（项目顺序也调换，顺序无关）：
433		// 必须作为首次成功录入接受并置为待判定，不能因与失败尝试内容不同而报冲突。
434		saved, err := s.SubmitSample("S2", "P1", at(10, 0),
435			Measurement{Item: "COD", Value: 25}, Measurement{Item: "pH", Value: 6})
436		if err != nil {
437			t.Fatalf("submit after save restored should succeed: %v", err)
438		}
439		if saved.ID != "S2" || saved.PointID != "P1" || saved.Status != StatusPending {
440			t.Fatalf("saved sample should be pending: %+v", saved)
441		}
442		if saved.Exceeded || saved.Results != nil || saved.VoidReason != "" {
443			t.Fatalf("new sample must carry no verdict or void reason: %+v", saved)
444		}
445		if vs := valuesOf(saved); len(vs) != 2 || vs["pH"] != 6 || vs["COD"] != 25 {
446			t.Fatalf("saved measurements should match this submission: %+v", saved.Measurements)
447		}
448	
449		// 已成功保存样品的重复提交行为保持不变：同内容（顺序无关）幂等返回原记录；
450		// 不同内容仍整次拒绝——哪怕填入的正是上次失败尝试里的值 7。
451		idem, err := s.SubmitSample("S2", "P1", at(10, 0),
452			Measurement{Item: "COD", Value: 25}, Measurement{Item: "pH", Value: 6})
453		if err != nil || idem.ID != "S2" || idem.Status != StatusPending || valuesOf(idem)["pH"] != 6 {
454			t.Fatalf("identical resubmit should return the saved pending sample, got %+v err=%v", idem, err)
455		}
456		if _, err := s.SubmitSample("S2", "P1", at(10, 0),
457			Measurement{Item: "pH", Value: 7}, Measurement{Item: "COD", Value: 25}); !errors.Is(err, ErrSampleConflict) {
458			t.Fatalf("different content against the saved sample should conflict, got %v", err)
459		}
460	
461		// 查询中只出现一份该编号的待判定样品，两个项目及数值以本次成功提交为准，
462		// 没有判定结果或作废原因；较早样品仍是原样的已确认记录。
463		list2, err := s.ListByPoint("P1")
464		if err != nil || len(list2) != 2 {
465			t.Fatalf("ListByPoint after recovery: %+v err=%v", list2, err)
466		}
467		if list2[0].ID != "S2" || list2[1].ID != "S1" {
468			t.Fatalf("order should put the later S2 first: %+v", list2)
469		}
470		fresh := find(list2, "S2")
471		if fresh.Status != StatusPending || fresh.Exceeded || fresh.Results != nil || fresh.VoidReason != "" {
472			t.Fatalf("S2 should be a single pending sample without verdict: %+v", fresh)
473		}
474		if vs := valuesOf(fresh); len(vs) != 2 || vs["pH"] != 6 || vs["COD"] != 25 {
475			t.Fatalf("S2 measurements must come from the successful submission: %+v", fresh.Measurements)
476		}
477		checkEarlier(find(list2, "S1"), "恢复后较早样品")
478		// 新样品尚未确认，最近有效结果仍指向较早的 S1。
479		latest2, ok, err := s.LatestResult("P1")
480		if err != nil || !ok || latest2.ID != "S1" {
481			t.Fatalf("latest valid result should still be S1, got %+v ok=%v err=%v", latest2, ok, err)
482		}
483		checkEarlier(latest2, "恢复后最近有效结果")
484	
485		// 重新打开同一数据存放：成功提交的内容仍在，失败尝试的测量值 7 没有混入；
486		// 较早样品的确认记录与最近有效结果身份也保持不变。
487		if err := s.Close(); err != nil {
488			t.Fatalf("Close: %v", err)
489		}
490		s2, err := Open(dir)
491		if err != nil {
492			t.Fatalf("reopen: %v", err)
493		}
494		defer s2.Close()
495		list3, err := s2.ListByPoint("P1")
496		if err != nil || len(list3) != 2 {
497			t.Fatalf("reopened ListByPoint: %+v err=%v", list3, err)
498		}
499		reopened := find(list3, "S2")
500		if reopened.Status != StatusPending || reopened.Exceeded || reopened.Results != nil || reopened.VoidReason != "" {
501			t.Fatalf("reopened S2 should stay pending without verdict: %+v", reopened)
502		}
503		if vs := valuesOf(reopened); len(vs) != 2 || vs["pH"] != 6 || vs["COD"] != 25 {
504			t.Fatalf("failed-attempt measurement leaked into the saved record: %+v", reopened.Measurements)
505		}
506		checkEarlier(find(list3, "S1"), "重开后较早样品")
507		latest3, ok, err := s2.LatestResult("P1")
508		if err != nil || !ok || latest3.ID != "S1" {
509			t.Fatalf("reopened latest should stay S1, got %+v ok=%v err=%v", latest3, ok, err)
510		}
511		checkEarlier(latest3, "重开后最近有效结果")
512	}
